layer.css:
[data-ryt="footer"] { color: var(--ryt-accent); border-top: 1px solid rgb(59, 59, 59); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="header"] { border-bottom: 1px solid rgb(59, 59, 59); border-top: none }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: system-ui, -apple-system, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", "liberation sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-accent); border-radius: 0px; font-family: system-ui, -apple-system, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", "liberation sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: inherit; color: rgb(255, 255, 255) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: inherit; color: rgb(255, 255, 255) }
